class Solution { public:string shortestBeautifulSubstring(string s,int k){int left=0,ones=0;string answer;for(int right=0;right<(int)s.size();++right){if(s[right]=='1')++ones;while(left<=right&&(s[left]=='0'||ones>k))if(s[left++]=='1')--ones;if(ones==k){string candidate=s.substr(left,right-left+1);if(answer.empty()||candidate.size()<answer.size()||candidate.size()==answer.size()&&candidate<answer)answer=candidate;}}return answer;} };
